def parts(t: dict) -> str:
    """Ж-225 п. 9: (а) историческое снижение ошибки на окне выбора, (б) историческое подтверждение 2022–02.2026, (в) экономическая значимость."""
    a, b = DOC.idx(t), t["top"][0]
    g = lambda w, c, s=b: float(a.loc[(s, w), c])
    d = lambda w: ", ".join("%s %+.2f %%" % (r.upper(), g(w, "d_qlike_%s_pct_of_k1" % r)) for r in DOC.REFS)
    sm = a.xs("all", level="window")["qlike_simple_2017_2021"]
    bs = sm[[c for c in FD.CFGS]].idxmin()
    return ("**(а) Снижение исторической ошибки на окне выбора 2017–2021 (M16, WALK-FORWARD).** Лучшая по `crit_panel` — %s: crit_panel %.5f (K1 %.5f, K2 %.5f, K3 %.5f, D2 %.5f), простое среднее QLIKE %.5f. Δ QLIKE (%% уровня K1; минус — лучше): %s. "
            "По 2017 отдельно: %s; по 2018 отдельно: %s. По простому среднему окна выбора лучшая конфигурация — %s (%.5f).\n\n"
            "**(б) Подтверждение на 2022–02.2026 — историческое, многократно изученное, НЕ независимый OOS.** %s на 2022–2025: %s; на 2026 (38 дат, неполный): %s.\n\n"
            "**(в) Экономическая значимость — не оценивалась** (торговые стратегии заданием запрещены; перевод снижения QLIKE в деньги не делался)."
            % (b, g("all", "crit_panel"), g("all", "crit_panel", "k1"), g("all", "crit_panel", "k2"), g("all", "crit_panel", "k3"), g("all", "crit_panel", "d2"), g("all", "qlike_simple_2017_2021"), d("2017_2021"), d("2017"), d("2018"),
               bs, float(sm[bs]), b, d("2022_2025"), d("2026")))


def oracle_block() -> str:
    o = IO.read_csv("A_ORACLE.csv")
    o = o[(o["m"] == "KG") & o["ticker"].isin(["M16", "SBER"])]
    rows = ["| %s | %s | %.4f | %.4f | %.4f | %.4f | %.4f | %.1f %% | %.1f %% | %.1f %% | %.1f %% |" % (r.ticker, r.window, r.q_best, r.o1, r.o2, r.o3, r.o4, 100 * r.s1_const_weight, 100 * r.s2_conditional, 100 * r.s3_out_of_range, 100 * r.s4_residual)
            for r in o.itertuples() if r.window in ("2017_2021", "2022_2025", "all")]
    return DOC._hdr(["группа", "окно", "лучшая одиночная", "O1", "O2", "O3", "O4 {H,K2,K3}", "постоянный вес", "условный вес", "выход за диапазон", "остаток (нужна новая информация)"]) + "\n".join(rows) + "\n"


def dx_block() -> str:
    y = IO.read_csv("DX_YEARS.csv")
    y = y[(y["m"] == "KG") & (y["group"] == "M16")]
    rows = ["| %s | %+.4f | %.2f [%.2f; %.2f] | %s | %.1f | %.1f / %.1f / %.1f |" % (r.slice, r.d_mean, r.w_har, r.w_har_lo90, r.w_har_hi90, DOC.yn(r.ml_encompasses_har), 100 * r.share_outside, r.gain_o1_pct, r.gain_o2_pct, r.gain_o3_pct)
            for r in y.itertuples()]
    return DOC._hdr(["срез (год цели)", "D̄ = QLIKE(H) − QLIKE(M)", "вес HAR-J [90 %]", "ML охватывает HAR-J", "RV вне [H; M], % дней", "O1 / O2 / O3, % QLIKE лучшей одиночной"]) + "\n".join(rows) + "\n"


def explain(t: dict) -> str:
    """Количественное объяснение: почему гибриды не превосходят самостоятельные бустинги устойчиво (числа — таблицы этапов и FIN_ALL)."""
    a, b = DOC.idx(t), t["top"][0]
    g = lambda w, r: float(a.loc[(b, w), "d_qlike_%s_pct_of_k1" % r])
    k8, c2, c3 = float(a.loc[("K8", "all"), "crit_panel"]), DOC.yn(a.loc[(b, "all"), "c2"]), DOC.yn(a.loc[(b, "all"), "c3"])
    return ("1. **Диапазон двух прогнозов слишком узок.** RV лежит вне [min(H, M); max(H, M)] в 92,3 % дней M16 (H_REPORT; DX_YEARS.csv: 91–93 % по годам) и эти дни несут 99,7 % потерь; поэтому выпуклая смесь H и M даже с идеальным постоянным весом (O1) снимает лишь 0,9 % QLIKE лучшей одиночной модели, с идеальным дневным весом внутри диапазона (O2) — 13,8 %, остаток 86 % требует информации вне прогнозов (таблица oracle выше; A_ORACLE.csv). Реальный условный выигрыш — малая часть O2.\n"
            "2. **Ошибки почти совпадают.** Корреляция логарифмических ошибок на M16 (вся история): H–K2 0,966, H–K3 0,963, K2–K3 0,995 (A_REPORT, A_COMPLEMENT.csv): K2 и K3 — практически одна модель, поэтому смесь K2·K3 диверсификации не даёт, а к HAR-J добавляет выигрыш только там, где HAR-J информативен.\n"
            f"3. **HAR-J информативен в одном году.** По DX_YEARS.csv (таблица выше) HAR-J лучше √(K2·K3) только в 2018 (вес 1,13 [0,30; 1,87]); в 2022–2025 вес HAR-J −0,06 [−0,52; 0,36] — ML охватывает HAR-J; в 4 из 10 лет интервал веса HAR-J включает 0. Δ QLIKE {b} к K2 (% уровня K1, минус — лучше): 2018 {g('2018', 'k2'):+.2f} %, 2022–2025 {g('2022_2025', 'k2'):+.2f} % (FIN_ALL.csv): преимущество гибрида держится на одном году окна выбора и не переносится.\n"
            f"4. **Дифференциал потерь не предсказуем.** CLD1: R² OOS −0,0041 (2017–2021), −0,0098 (2022–2025), корреляция D̂ с D −0,003 (CLD_REPORT, CLD_PRED.csv); вес почти константа (0,501 ± 0,021), выигрыш CLD1 даёт сжатие к 0,5, а не условность. Равновесная смесь K8 = √(H·M) без параметров (crit_panel {k8:.5f}) лучше всех 31 гибрида, оценённых к моменту её расчёта (RQC_REPORT).\n"
            "5. **Новая информация не нашлась.** Ни один из источников H1–H8 (рыночный и секторный HAR-surprise, внутридневная форма, вероятность скачка, согласованность, CUSUM) не дал условной ценности сверх K8 (H_VALUE.csv: ценность «нет» у всех восьми; DM p ≥ 0,05 на всей истории, кроме ухудшения H6 с p = 0,010). Компонентный прогноз I1 (C + J без HAR-J и ML) хуже K1 на +6,04 % уровня K1 (I_REPORT): HAR-J уже учитывает ожидаемый вклад скачков.\n"
            "6. **Адаптивная калибровка и онлайн-веса вредят после шоков.** E1–E6: crit_panel от 0,26929 до 0,27815 против K1 0,26220 (E_REPORT), поправка перескакивает после шоков (2022-02-24..03-31: b до +0,50); RQC3 структурно хуже K8 на +0,03323 crit_panel (RQC_REPORT). NTP и Cold Start не улучшили C8 (потери холодного старта 2017 не больше 0,0005 QLIKE, CS_REPORT).\n"
            f"7. **Лучшая по crit_panel ({b}) и крайние дни.** Условие (2) «без целей 2017»: {c2}; условие (3) «без 1 % дат с наибольшей разностью к лучшему из K2/K3»: {c3} (таблица всех архитектур). Δ QLIKE {b} к K2 / K3 / D2 на 2022–2025: {g('2022_2025', 'k2'):+.2f} % / {g('2022_2025', 'k3'):+.2f} % / {g('2022_2025', 'd2'):+.2f} % уровня K1.")


def year_weights(t: dict) -> str:
    return ("Находка (дирижёр, журнал 08.11, строка «≡ [V4]» после листа NTP): `crit_panel` (Ж-217) = среднее по M16 `crit_wf`, где для Y = 2018…2021 pen_Y = среднее годовых QLIKE лет < Y + 0,25·(максимум − среднее), crit = среднее pen_Y; эффективные веса годов цели окна 2017–2021: 2017 ≈ 0,52, 2018 ≈ 0,27, 2019 ≈ 0,15, 2020 ≈ 0,06, 2021 — 0, плюс штраф худшего прошлого года (число из журнала; "
            "тождество «сумма crit_part = crit_panel» проверяется в `--check` по `FIN_YEARS.csv`). Следствие: по объявленному `crit_panel` ни одна архитектура не проходит первое условие у большинства этапов, а по простому среднему QLIKE 2017–2021 (равные веса годов) ряд конфигураций лучше всех контролей. "
            "В этом документе ВЕЗДЕ приведены обе меры (столбцы «crit_panel» и «простое ср. 2017–2021»); выводы — по объявленному `crit_panel` и ужесточённому «go» (критерий не менялся, умолчание вопроса «❓ [V4] пакет 10:00»: ответа владельца в журнале на момент сборки нет). Изменение критерия — класс A, отступление от предрегистрации с обеими версиями.")


def registry_table(t: dict) -> str:
    a = DOC.idx(t)
    rows = ["| %s | %s | %.5f | %s |" % (s, FD.STAGE_OF[s], a.loc[(s, "all"), "crit_panel"], DOC.yn(a.loc[(s, "all"), "go"])) for s in FD.CFGS]
    return DOC._hdr(["конфигурация", "этап", "crit_panel", "go"]) + "\n".join(rows) + "\n"
